     3	import hotel.reservations.Reservation;
     4	import java.util.List;
     5	
     6	/**
     7	 * Every report has the same shape: the title line (the inn, the report's name, the period), the header, one line
     8	 * per row, and the total line. Each report says only what changes: its name, its columns, which reservations
     9	 * count, its rows and its total.
    10	 */
    11	public abstract class CsvReport<P> {
    12	
    13	    static final String HOTEL_NAME = "Pousada Maré Alta";
    14	
    15	    public final String generate(P period) {
    16	        List<Reservation> selected = select(period);
    17	        StringBuilder csv = new StringBuilder();
    18	        csv.append(HOTEL_NAME).append(',').append(name()).append(',').append(period).append('\n');
    19	        csv.append(header()).append('\n');
    20	        for (String row : rows(selected)) {
    21	            csv.append(row).append('\n');
    22	        }
    23	        csv.append("total,").append(total(selected)).append('\n');
    24	        return csv.toString();
    25	    }
    26	
    27	    protected abstract String name();
    28	
    29	    protected abstract String header();
    30	
    31	    /** The reservations the report is about, in the report's order. */
    32	    protected abstract List<Reservation> select(P period);
    33	
    34	    protected abstract List<String> rows(List<Reservation> selected);
    35	
    36	    /** What comes after "total," on the last line. */
    37	    protected abstract String total(List<Reservation> selected);
    38	}
