 45	import java.time.LocalDate;
 46	import java.time.Month;
 47	
 48	/**
 49	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
 50	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
 51	 * (half-even) at every step.
 52	 */
 53	public final class PriceCalculator {
 54	
 55	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
 56	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
 57	
 58	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
 59	        int nights = 0;
 60	        BigDecimal subtotal = cents(BigDecimal.ZERO);
 61	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
 62	            subtotal = subtotal.add(nightPrice(room, night));
 63	            nights++;
 64	        }
 65	        BigDecimal discount = switch (ratePlan) {
 66	            case STANDARD -> cents(BigDecimal.ZERO);
 67	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
 68	        };
 69	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
 70	    }
 71	
 72	    BigDecimal nightPrice(Room room, LocalDate night) {
 73	        BigDecimal nightlyRate = room.nightlyRate();
 74	        if (isHighSeason(night)) {
 75	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
 76	        }
 77	        return cents(nightlyRate);
 78	    }
 79	
 80	    /** High season: from December 15 to the end of February, and the whole of July. */
 81	    static boolean isHighSeason(LocalDate date) {
 82	        Month month = date.getMonth();
 83	        return month == Month.JANUARY
 84	                || month == Month.FEBRUARY
 85	                || month == Month.JULY
 86	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
 87	    }
 88	
 89	    static BigDecimal cents(BigDecimal value) {
 90	        return value.setScale(2, RoundingMode.HALF_EVEN);
 91	    }
 92	}
